{"command": "python3 -c "
import hashlib, json

def sha256(fpath):
    h = hashlib.sha256()
    with open(fpath, 'rb') as f:
        for chunk in iter(lambda: f.read(65536), b''):
            h.update(chunk)
    return h.hexdigest()

base = '/srv/jwteam_clone/shared/run_current/workspace'

# Compute actual checksums
actual = {
    'source': {},
    'transformed': {}
}

actual['source']['devices.csv'] = sha256(f'{base}/data/old_format/devices.csv')
actual['source']['sensor_readings.csv'] = sha256(f'{base}/data/old_format/sensor_readings.csv')
actual['transformed']['devices.jsonl'] = sha256(f'{base}/data/transformed/devices.jsonl')
actual['transformed']['sensor_readings.jsonl'] = sha256(f'{base}/data/transformed/sensor_readings.jsonl')

# Read reported checksums
with open(f'{base}/checksums.json') as f:
    reported = json.load(f)

# Compare
all_match = True
for section in ['source', 'transformed']:
    for fname, expected in reported[section].items():
        actual_val = actual[section][fname]
        match = actual_val == expected
        flag = 'PASS' if match else 'FAIL'
        print(f'{flag}: {section}/{fname} - reported={expected[:16]}... actual={actual_val[:16]}... match={match}')
        if not match:
            all_match = False

print()
if all_match:
    print('ALL CHECKSUMS VERIFIED')
else:
    print('CHECKSUM MISMATCH DETECTED')
